  const changes=[];
  result[sheet]=original[sheet].replace(/<row\b([^>]*)>([\s\S]*?)<\/row>/g,(whole,attributes,cells)=>{
   const declared=/\br="(\d+)"/.exec(attributes);if(!declared)return whole;
   const rows=[...cells.matchAll(/<c\b[^>]*\br="[A-Z]+(\d+)"/g)].map(match=>match[1]);
   assert.ok(rows.length>0);assert.equal(new Set(rows).size,1,'A numbered synthetic row may not mix cell rows');
   changes.push(declared[1]);return '<row'+attributes.replace(/\br="\d+"/,'r="'+rows[0]+'"')+'>'+cells+'</row>';
  });
  let index=0;
  const restored=result[sheet].replace(/<row\b([^>]*)>([\s\S]*?)<\/row>/g,(whole,attributes,cells)=>/\br="\d+"/.test(attributes)?'<row'+attributes.replace(/\br="\d+"/,'r="'+changes[index++]+'"')+'>'+cells+'</row>':whole);
